// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *SubscribeNotificationsRequest) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	if m.decoded && m.seen&(uint64(1)<<0) == 0 {
		return diam.Missing(263, 0, "SESSION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<1) == 0 {
		return diam.Missing(260, 0, "VENDOR_SPECIFIC_APPLICATION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<2) == 0 {
		return diam.Missing(277, 0, "AUTH_SESSION_STATE")
	}
	if m.decoded && m.seen&(uint64(1)<<3) == 0 {
		return diam.Missing(264, 0, "ORIGIN_HOST")
	}
	if m.decoded && m.seen&(uint64(1)<<4) == 0 {
		return diam.Missing(296, 0, "ORIGIN_REALM")
	}
	if m.decoded && m.seen&(uint64(1)<<5) == 0 {
		return diam.Missing(283, 0, "DESTINATION_REALM")
	}
	if m.decoded && m.seen&(uint64(1)<<6) == 0 {
		return diam.Missing(700, 10415, "USER_IDENTITY")
	}
	if m.decoded && m.seen&(uint64(1)<<7) == 0 {
		return diam.Missing(705, 10415, "SUBS_REQ_TYPE")
	}
	if len(m.DataReference) < 1 {
		return diam.TooFew(703, 10415, "DATA_REFERENCE", 1)
	}
	if m.misplaced != nil {
		return m.misplaced
	}
	if err := m.VendorSpecificApplicationId.Validate(); err != nil {
		return diam.InGroup(err, 260)
	}
	for i := range m.SupportedFeatures {
		if err := m.SupportedFeatures[i].Validate(); err != nil {
			return diam.InGroup(err, 628)
		}
	}
	if err := m.UserIdentity.Validate(); err != nil {
		return diam.InGroup(err, 700)
	}
	if m.OcSupportedFeatures != nil {
		if err := m.OcSupportedFeatures.Validate(); err != nil {
			return diam.InGroup(err, 621)
		}
	}
	for i := range m.ProxyInfo {
		if err := m.ProxyInfo[i].Validate(); err != nil {
			return diam.InGroup(err, 284)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

// DiamHeader implements diam.Message.
func (m *SubscribeNotificationsRequest) DiamHeader() *diam.Header { return &m.Header }

// AppendMarshal appends the encoded message to b. The command code, the
// application id and the R and P bits come from the grammar; the E and T
// bits and the identifiers come from m.Header, which is not modified.
func (m *SubscribeNotificationsRequest) AppendMarshal(b []byte) ([]byte, error) {
	h := m.Header
	h.CommandCode, h.AppID = 308, 16777217
	h.Flags = h.Flags&^(diam.FlagRequest|diam.FlagProxiable) | diam.FlagRequest | diam.FlagProxiable
	start := len(b)
	b = diam.AppendHeader(b, &h)
	b = m.AppendAVPs(b)
	return diam.FinishMessage(b, start)
}

// Marshal encodes the message.
func (m *SubscribeNotificationsRequest) Marshal() ([]byte, error) { return m.AppendMarshal(nil) }

// Unmarshal decodes a whole message into m, replacing its contents. It
// fails only when the message cannot be framed; grammar violations are
// reported by Validate.
func (m *SubscribeNotificationsRequest) Unmarshal(b []byte) error {
	h, avps, err := diam.ParseHeader(b)
	if err != nil {
		return err
	}
	m.Header = h
	return m.DecodeAVPs(avps)
}

